WITH flattened AS (SELECT id, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers) SELECT id, tier_value, RANK() OVER w_hist AS tier_value_rank, DENSE_RANK() OVER (ORDER BY tier_value DESC) AS tier_value_dense_rank, PERCENT_RANK() OVER w_hist AS tier_value_percent_rank, PERCENT_RANK() OVER w_hist AS tier_value_percent_rank_2, DENSE_RANK() OVER (ORDER BY tier_value DESC NULLS FIRST) AS tier_value_dense_rank_2 FROM flattened WINDOW w_hist AS (ORDER BY tier_value DESC NULLS LAST)
